ALTER POLICY categories_read ON public.categories USING (nullif(btrim(slug), '') IS NOT NULL);
ALTER POLICY events_read ON public.events USING (nullif(btrim(slug), '') IS NOT NULL AND status IN ('live','scheduled','active','finished','recebendo_lances','incondicional','em_condicional','em_loteamento'));
ALTER POLICY lots_read ON public.lots USING (status IN ('upcoming','active','live','recebendo_lances','pre_lance','sold','finished','passed') AND EXISTS (SELECT 1 FROM public.events e WHERE e.id = event_id AND nullif(btrim(e.slug), '') IS NOT NULL AND e.status IN ('live','scheduled','active','finished','recebendo_lances','incondicional','em_condicional','em_loteamento')));
ALTER POLICY animals_read ON public.animals USING ((is_direct_sale IS TRUE AND sale_status = 'available') OR EXISTS (SELECT 1 FROM public.lots l JOIN public.events e ON e.id = l.event_id WHERE l.animal_id = animals.id AND l.status IN ('upcoming','active','live','recebendo_lances','pre_lance','sold','finished','passed') AND nullif(btrim(e.slug), '') IS NOT NULL AND e.status IN ('live','scheduled','active','finished','recebendo_lances','incondicional','em_condicional','em_loteamento')));